/// <summary>
        /// 按订单ID分组清账记录
        /// </summary>
        private Dictionary<string, List<ClearRecon>> GroupClearReconsByOrderId(
            List<(string OrderId, ClearRecon ClearRecon)> clearRecons)
        {
            return clearRecons
                .GroupBy(r => r.OrderId)
                .ToDictionary(
                    g => g.Key,
                    g => g.Select(r => r.ClearRecon)
                          .OrderBy(r => r.CreateDate)
                          .ToList());
